## Setup

```sql
-- Add a generated tsvector column (auto-updates on INSERT/UPDATE)
ALTER TABLE articles ADD COLUMN search_vector TSVECTOR
    GENERATED ALWAYS AS (
        setweight(to_tsvector('english', coalesce(title, '')), 'A') ||
        setweight(to_tsvector('english', coalesce(content, '')), 'B')
    ) STORED;
-- Title matches get higher weight (A) than content matches (B)

-- GIN index for fast search
CREATE INDEX idx_articles_fts ON articles USING GIN (search_vector);
```

## Searching

```sql
-- Basic search: articles about 'java spring'
SELECT id, title,
       ts_rank(search_vector, query) AS relevance
FROM articles,
     to_tsquery('english', 'java & spring') AS query
WHERE search_vector @@ query
ORDER BY relevance DESC
LIMIT 20;

-- Phrase search: 'dependency injection' as phrase
WHERE search_vector @@ to_tsquery('english', 'dependency <-> injection')

-- Highlight matches in results
SELECT ts_headline('english', content, to_tsquery('java & spring'))
FROM articles WHERE search_vector @@ to_tsquery('java & spring');
```

## Spring Implementation

```java
@Repository
public interface ArticleRepository extends JpaRepository<Article, Long> {

    @Query(value = """
        SELECT id, title, ts_rank(search_vector, query) AS rank
        FROM articles,
             to_tsquery('english', :searchQuery) AS query
        WHERE search_vector @@ query
        ORDER BY rank DESC
        LIMIT :limit
        """, nativeQuery = true)
    List<Object[]> fullTextSearch(
        @Param("searchQuery") String searchQuery,
        @Param("limit") int limit
    );
}

// Convert user input to tsquery format (handle special characters)
public String toTsQuery(String input) {
    // Convert 'java spring boot' to 'java & spring & boot'
    return Arrays.stream(input.trim().split("\\s+"))
        .filter(w -> w.length() > 1)
        .map(w -> w.replaceAll("[^a-zA-Z0-9]", ""))
        .filter(w -> !w.isEmpty())
        .collect(Collectors.joining(" & "));
}
```

## Schema Setup

```sql
-- Create application schema (don't use 'public' for app tables)
CREATE SCHEMA app;

-- Create roles
CREATE ROLE app_user LOGIN PASSWORD 'securepassword';
CREATE ROLE app_readonly LOGIN PASSWORD 'readonlypassword';
CREATE ROLE migrations LOGIN PASSWORD 'migrationpassword';

-- App role: data operations only
GRANT USAGE ON SCHEMA app TO app_user;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA app TO app_user;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA app TO app_user;
-- Future tables created in this schema automatically get privileges
ALTER DEFAULT PRIVILEGES IN SCHEMA app
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO app_user;

-- Read-only role for reporting
GRANT USAGE ON SCHEMA app TO app_readonly;
GRANT SELECT ON ALL TABLES IN SCHEMA app TO app_readonly;

-- Migrations role: full schema control
GRANT ALL ON SCHEMA app TO migrations;
```

## Row-Level Security (Multi-Tenant)

```sql
-- Enable RLS on the table
ALTER TABLE app.orders ENABLE ROW LEVEL SECURITY;

-- Policy: each tenant only sees their own rows
CREATE POLICY tenant_isolation ON app.orders
    USING (tenant_id = current_setting('app.current_tenant_id')::INTEGER);

-- Application sets the tenant context at session start
-- In Spring: use a DataSource proxy or servlet filter
```

```java
// Set tenant context before each request
@Component
public class TenantFilter implements Filter {
    @Autowired DataSource dataSource;

    public void doFilter(ServletRequest req, ...) {
        String tenantId = extractTenantFromJwt(req);
        try (Connection conn = dataSource.getConnection()) {
            conn.createStatement().execute(
                "SET app.current_tenant_id = '" + tenantId + "'"  // sanitize!
            );
        }
        chain.doFilter(req, res);
    }
}
```

