## Streaming Replication Setup (PostgreSQL configuration)

```ini
# postgresql.conf on primary
wal_level = replica
max_wal_senders = 3
wal_keep_size = 1GB

# pg_hba.conf on primary — allow replica to connect
# TYPE   DATABASE  USER         ADDRESS     METHOD
host     replication replicator  10.0.0.2/32 scram-sha-256
```

```bash
# Initialize replica from primary
pg_basebackup -h primary-host -U replicator -D /var/lib/postgresql/data --wal-method=stream
```

## Spring: Read/Write Routing DataSource

```java
@Configuration
public class DataSourceConfig {

    @Bean
    @Primary
    public DataSource routingDataSource(
        @Qualifier("primaryDataSource") DataSource primary,
        @Qualifier("replicaDataSource") DataSource replica
    ) {
        Map<Object, Object> sources = new HashMap<>();
        sources.put("primary", primary);
        sources.put("replica",  replica);

        AbstractRoutingDataSource routing = new AbstractRoutingDataSource() {
            @Override
            protected Object determineCurrentLookupKey() {
                // Route read-only transactions to replica
                return TransactionSynchronizationManager.isCurrentTransactionReadOnly()
                    ? "replica" : "primary";
            }
        };
        routing.setTargetDataSources(sources);
        routing.setDefaultTargetDataSource(primary);
        return routing;
    }
}

// Usage:
@Transactional(readOnly = true)  // → routes to replica
public List<Product> getAllProducts() { ... }

@Transactional                   // → routes to primary
public Product createProduct(ProductDTO dto) { ... }
```

## Lag Monitoring

```sql
-- On replica: check how far behind primary
SELECT NOW() - pg_last_xact_replay_timestamp() AS replication_lag;

-- On primary: check all replica lag
SELECT client_addr,
       write_lag, flush_lag, replay_lag
FROM pg_stat_replication;
```

**Spring Boot transaction isolation:**
```java
// Default: READ_COMMITTED (usually correct)
@Transactional
public void processOrder(Long orderId) {
    Order order = orderRepo.findById(orderId).orElseThrow();
    // Each SELECT sees latest committed data
    inventoryService.reserve(order);
    paymentService.charge(order);
}

// REPEATABLE_READ: when consistent view across multiple reads is required
@Transactional(isolation = Isolation.REPEATABLE_READ)
public Report generateReport(LocalDate date) {
    List<Order> orders = orderRepo.findByDate(date);
    // All reads within this transaction see same snapshot
    BigDecimal total = orderRepo.sumByDate(date); // same set as above
    return new Report(orders, total);
}

// SERIALIZABLE: when logic depends on nothing changing (use sparingly)
@Transactional(isolation = Isolation.SERIALIZABLE)
public void transferFunds(Account from, Account to, BigDecimal amount) {
    // Full serializable isolation — may throw SerializationException
    // Caller MUST handle retry!
}

// OPTIMISTIC LOCKING (often better than SERIALIZABLE):
@Version
private Long version; // @Entity field
// Hibernate auto-adds WHERE version=:expected on UPDATE
// Throws OptimisticLockingFailureException on conflict
```

Here's exactly how the deadlock happens — notice how each transaction locks rows in a different order:

```sql
-- Transaction 1: checkout for order with products [A, B]
BEGIN;
UPDATE inventory SET quantity = quantity - 1 WHERE product_id = 'A';
-- ↑ Acquires exclusive row lock on product A
-- ↓ Now needs lock on B, but Tx2 already holds it → BLOCKS
UPDATE inventory SET quantity = quantity - 1 WHERE product_id = 'B';
COMMIT;

-- Transaction 2 (concurrent): checkout for products [B, A]
BEGIN;
UPDATE inventory SET quantity = quantity - 1 WHERE product_id = 'B';
-- ↑ Acquires exclusive row lock on product B
-- ↓ Now needs lock on A, but Tx1 already holds it → BLOCKS
UPDATE inventory SET quantity = quantity - 1 WHERE product_id = 'A';
COMMIT;

-- RESULT: Circular wait detected after deadlock_timeout (1s)
-- PostgreSQL picks the cheaper transaction and aborts it:
-- ERROR: deadlock detected
-- DETAIL: Process 12345 waits for ShareLock on transaction 67890;
--         blocked by process 67891.
-- Your application MUST catch this and retry the transaction.
```

@Entity
public class Order {
    @OneToMany(mappedBy = "order", fetch = FetchType.LAZY) // LAZY is correct default
    private List<OrderItem> items;
}

// SERVICE: loads orders (1 query)
List<Order> orders = orderRepository.findByUserId(userId); // SELECT * FROM orders

// TEMPLATE/CONTROLLER: iterates and accesses items
for (Order order : orders) {
    log.info(order.getItems().size()); // EACH ACCESS → separate SELECT FROM order_items WHERE order_id=?
    // 100 orders = 100 extra queries!
}
// SQL log: 101 queries, 2 seconds total
// vs optimal: 2 queries, 50ms total

// SOLUTION 1: JOIN FETCH (best for single association)
public interface OrderRepository extends JpaRepository<Order, Long> {
    @Query("SELECT DISTINCT o FROM Order o " +
           "LEFT JOIN FETCH o.items " +
           "WHERE o.userId = :userId")
    List<Order> findByUserIdWithItems(@Param("userId") Long userId);
    // Generates: SELECT o.*, i.* FROM orders o LEFT JOIN order_items i ON ...
    // 1 query!
}

// SOLUTION 2: @EntityGraph (annotation-based, no JPQL)
@EntityGraph(attributePaths = {"items", "items.product"})  // eager in this query
List<Order> findByUserId(Long userId);

// SOLUTION 3: Batch fetching (for multiple associations or complex graphs)
// application.yml:
// spring.jpa.properties.hibernate.default_batch_fetch_size: 20
// → loads items in batches: SELECT * FROM order_items WHERE order_id IN (1,2,...,20)
// Result: 1 order query + 5 item queries (for 100 orders) = 6 total

// SOLUTION 4: DTO Projection (best for read-heavy pages)
@Query("SELECT new com.myapp.dto.OrderSummary(o.id, o.total, COUNT(i)) "
     + "FROM Order o LEFT JOIN o.items i "
     + "WHERE o.userId = :userId "
     + "GROUP BY o.id, o.total")
List<OrderSummary> findOrderSummaries(@Param("userId") Long userId);
// No entity loading = no lazy loading = no N+1 possible
